/// The six scopes of spec section 12. A per-seat 256-bit token carries a set of
/// them; the gateway checks the one `required_scope` names before the method
/// runs.
///
/// Two invariants are asserted in the gateway's code and are not expressible
/// here: a SEAT token can never hold SCOPE_SPECTATE_NOFOG (only a separate
/// spectator token can), and SCOPE_ADMIN can never read another seat's
/// playbooks, drafts or knowledge. Fog itself is a per-match server-side
/// policy, so no token is reissued mid-match.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum Scope {
    Unspecified = 0,
    /// Read the seat's own knowledge, status and feed.
    Observe = 1,
    /// Author: drafts, the notebook, verification, rendering, patching,
    /// templates and the safe playbook. Reads and writes the seat's own private
    /// state and nobody else's.
    Plan = 2,
    /// Seal: submit_plan and set_ready. Separate from SCOPE_PLAN because filing
    /// an order is the irrevocable act the whole game is about.
    PlanSubmit = 3,
    /// Generated schema and template listings. Carries no match state at all,
    /// which is why it is its own scope.
    Docs = 4,
    /// Spectator only. A seat token can never hold it.
    SpectateNofog = 5,
    /// Lobby and match control. Never another seat's secrets.
    Admin = 6,
}
impl Scope {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "SCOPE_UNSPECIFIED",
            Self::Observe => "SCOPE_OBSERVE",
            Self::Plan => "SCOPE_PLAN",
            Self::PlanSubmit => "SCOPE_PLAN_SUBMIT",
            Self::Docs => "SCOPE_DOCS",
            Self::SpectateNofog => "SCOPE_SPECTATE_NOFOG",
            Self::Admin => "SCOPE_ADMIN",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "SCOPE_UNSPECIFIED" => Some(Self::Unspecified),
            "SCOPE_OBSERVE" => Some(Self::Observe),
            "SCOPE_PLAN" => Some(Self::Plan),
            "SCOPE_PLAN_SUBMIT" => Some(Self::PlanSubmit),
            "SCOPE_DOCS" => Some(Self::Docs),
            "SCOPE_SPECTATE_NOFOG" => Some(Self::SpectateNofog),
            "SCOPE_ADMIN" => Some(Self::Admin),
            _ => None,
        }
    }
}
